}
switch (grade) {
case 'A':
printf("Perfect!\n");
break;
case 'B':
printf("You did good!\n");
break;
case 'C':
printf("You did okay!\n");
break;
case 'D':
printf("At least it's not an F!\n");
break;
case 'F':
printf("YOU FAILED!\n");
break;
default:
printf("That's not a valid grade!\n");
}
if/else-if zinasidagi har bir tenglik tekshiruvi case-metkasiga, esa else — default ga
aylanadi; break switch dan chiqadi (bajarish yopuvchi qavsdan keyin davom etadi
— break dasturni tugatmaydi). Ikkala dastur ham barcha A/B/C/D/F va W baholari
uchun bir xil xabarlarni beradi. Bir nechta case-metkalari ketma-ket joylashtiriladi:
switch (ch) {
case 'Y':
/* ch == 'Y' */
/* do something */
break;
case 'N':
/* ch == 'N' */
/* do something else */
break;
default:
/* otherwise */
/* do a third thing */
break;
}
switch (ch) {
case 'Y':
case 'y':
/* do something if ch == 'Y' or ch == 'y' */
break;
